 END LOOP;
 FOR pin IN SELECT value FROM jsonb_array_elements('[{"name":"accounting_tournament_fee_batches","owner":"postgres","acl":"{postgres=arwdDxtm/postgres,service_role=r/postgres}","rls":true,"forced_rls":false,"triggers":[{"name":"accounting_tournament_fee_batches_immutable","enabled":"O","definition":"CREATE TRIGGER accounting_tournament_fee_batches_immutable BEFORE DELETE OR UPDATE ON public.accounting_tournament_fee_batches FOR EACH ROW EXECUTE FUNCTION fn_accounting_tournament_fee_receipt_immutable()"},{"name":"accounting_tournament_fee_batches_no_truncate","enabled":"O","definition":"CREATE TRIGGER accounting_tournament_fee_batches_no_truncate BEFORE TRUNCATE ON public.accounting_tournament_fee_batches FOR EACH STATEMENT EXECUTE FUNCTION fn_accounting_tournament_fee_receipt_immutable()"}],"constraints":[{"name":"accounting_tournament_fee_batches_check","validated":true,"definition":"CHECK (((status = ''legacy_unverified''::text) OR (jsonb_typeof(source_manifest) = ''object''::text)))"},{"name":"accounting_tournament_fee_batches_pkey","validated":true,"definition":"PRIMARY KEY (rake_record_id)"},{"name":"accounting_tournament_fee_batches_rake_amount_check","validated":true,"definition":"CHECK (((rake_amount > (0)::numeric) AND (rake_amount = round(rake_amount, 2)) AND ((rake_amount)::text <> ALL (ARRAY[''NaN''::text, ''Infinity''::text, ''-Infinity''::text]))))"},{"name":"accounting_tournament_fee_batches_rake_record_id_fkey","validated":true,"definition":"FOREIGN KEY (rake_record_id) REFERENCES rake_records(id)"},{"name":"accounting_tournament_fee_batches_source_version_check","validated":true,"definition":"CHECK ((source_version = 2))"},{"name":"accounting_tournament_fee_batches_status_check","validated":true,"definition":"CHECK ((status = ANY (ARRAY[''captured''::text, ''legacy_unverified''::text])))"}]},{"name":"accounting_tournament_fee_cutover","owner":"postgres","acl":"{postgres=arwdDxtm/postgres,service_role=r/postgres}","rls":true,"forced_rls":false,"triggers":[{"name":"accounting_tournament_fee_cutover_immutable","enabled":"O","definition":"CREATE TRIGGER accounting_tournament_fee_cutover_immutable BEFORE DELETE OR UPDATE ON public.accounting_tournament_fee_cutover FOR EACH ROW EXECUTE FUNCTION fn_accounting_tournament_fee_receipt_immutable()"},{"name":"accounting_tournament_fee_cutover_no_truncate","enabled":"O","definition":"CREATE TRIGGER accounting_tournament_fee_cutover_no_truncate BEFORE TRUNCATE ON public.accounting_tournament_fee_cutover FOR EACH STATEMENT EXECUTE FUNCTION fn_accounting_tournament_fee_receipt_immutable()"}],"constraints":[{"name":"accounting_tournament_fee_cutover_pkey","validated":true,"definition":"PRIMARY KEY (singleton)"},{"name":"accounting_tournament_fee_cutover_singleton_check","validated":true,"definition":"CHECK (singleton)"}]},{"name":"accounting_tournament_fee_sources","owner":"postgres","acl":"{postgres=arwdDxtm/postgres,service_role=r/postgres}","rls":true,"forced_rls":false,"triggers":[{"name":"accounting_tournament_fee_sources_immutable","enabled":"O","definition":"CREATE TRIGGER accounting_tournament_fee_sources_immutable BEFORE DELETE OR UPDATE ON public.accounting_tournament_fee_sources FOR EACH ROW EXECUTE FUNCTION fn_accounting_tournament_fee_receipt_immutable()"},{"name":"accounting_tournament_fee_sources_no_truncate","enabled":"O","definition":"CREATE TRIGGER accounting_tournament_fee_sources_no_truncate BEFORE TRUNCATE ON public.accounting_tournament_fee_sources FOR EACH STATEMENT EXECUTE FUNCTION fn_accounting_tournament_fee_receipt_immutable()"}],"constraints":[{"name":"accounting_tournament_fee_sources_pkey","validated":true,"definition":"PRIMARY KEY (id)"},{"name":"accounting_tournament_fee_sources_rake_credit_check","validated":true,"definition":"CHECK (((rake_credit >= (0)::numeric) AND (rake_credit = round(rake_credit, 2)) AND ((rake_credit)::text <> ALL (ARRAY[''NaN''::text, ''Infinity''::text, ''-Infinity''::text]))))"},{"name":"accounting_tournament_fee_sources_rake_record_id_fkey","validated":true,"definition":"FOREIGN KEY (rake_record_id) REFERENCES accounting_tournament_fee_batches(rake_record_id)"},{"name":"accounting_tournament_fee_sources_rake_record_id_player_id_key","validated":true,"definition":"UNIQUE (rake_record_id, player_id)"},{"name":"accounting_tournament_fee_sources_source_entitlement_id_key","validated":true,"definition":"UNIQUE (source_entitlement_id)"}]}]'::jsonb) LOOP
  SELECT jsonb_build_object('owner',pg_get_userbyid(c.relowner),'acl',c.relacl::text,'rls',c.relrowsecurity,'forced_rls',c.relforcerowsecurity,
   'triggers',(SELECT jsonb_agg(jsonb_build_object('name',g.tgname,'definition',pg_get_triggerdef(g.oid),'enabled',g.tgenabled) ORDER BY g.tgname)
      FROM pg_trigger g WHERE g.tgrelid=c.oid AND NOT g.tgisinternal),
   'constraints',(SELECT jsonb_agg(jsonb_build_object('name',co.conname,'definition',pg_get_constraintdef(co.oid),'validated',co.convalidated) ORDER BY co.conname)
      FROM pg_constraint co WHERE co.conrelid=c.oid)) INTO actual FROM pg_class c WHERE c.oid=to_regclass('public.'||(pin->>'name'));
  IF actual IS DISTINCT FROM pin-'name' THEN RAISE EXCEPTION 'HISTORICAL_FEE_RECEIPT_SCHEMA_DRIFT: %',pin->>'name';END IF;
 END LOOP;
 IF (SELECT starts_at FROM public.accounting_tournament_fee_cutover WHERE singleton)
      IS DISTINCT FROM '2026-09-17 18:24:02.831517+00'::timestamptz THEN
  RAISE EXCEPTION 'HISTORICAL_FEE_CUTOVER_DRIFT'; END IF;
 -- Lock the two exact parents before any source write, matching terminal row
 -- ownership. A conflict times out and rolls back; no financial RPC is called.
 PERFORM 1 FROM public.tournaments WHERE id IN(
  '2c684c36-a1c0-40c6-b92a-610a86083c1b','fea2579a-643b-45d1-b22f-de654ce8ed23') ORDER BY id FOR NO KEY UPDATE;
 PERFORM 1 FROM public.rake_records WHERE id IN(
  'f7a5e3f5-49ce-4c17-9283-d260b39c2b0d','1229290b-448b-4015-99d2-955a093965fc','d00d2d87-9c08-44e7-80fd-6a695bc561df')
  ORDER BY id FOR SHARE;
 FOR expected IN SELECT value FROM jsonb_array_elements(plan) ORDER BY value->>'rake_id' LOOP
  PERFORM pg_advisory_xact_lock(hashtextextended('accounting_tournament_fee:'||(expected->>'rake_id'),0));
 END LOOP;
 -- No original fee, charge, entitlement, registration or history is rewritten.
 SELECT jsonb_build_object('rake',(SELECT jsonb_agg(to_jsonb(x) ORDER BY x.id) FROM public.rake_records x WHERE x.id IN(
  'f7a5e3f5-49ce-4c17-9283-d260b39c2b0d','1229290b-448b-4015-99d2-955a093965fc','d00d2d87-9c08-44e7-80fd-6a695bc561df')))
 INTO before_evidence;
 SELECT count(*) INTO present_batches FROM public.accounting_tournament_fee_batches b
  WHERE b.rake_record_id IN(SELECT (x->>'rake_id')::uuid FROM jsonb_array_elements(plan)x);
 SELECT count(*) INTO present_sources FROM public.accounting_tournament_fee_sources s
  WHERE s.rake_record_id IN(SELECT (x->>'rake_id')::uuid FROM jsonb_array_elements(plan)x);
 IF NOT((present_batches=0 AND present_sources=0) OR (present_batches=3 AND present_sources=3)) THEN
  RAISE EXCEPTION 'HISTORICAL_FEE_PARTIAL_CAPTURE_REFUSED';END IF;
 FOR expected IN SELECT value FROM jsonb_array_elements(plan) ORDER BY value->>'rake_id' LOOP
  record_id:=(expected->>'rake_id')::uuid;event_id:=(expected->>'tournament_id')::uuid;
  SELECT * INTO STRICT r FROM public.rake_records WHERE id=record_id;
  SELECT * INTO STRICT t FROM public.tournaments WHERE id=event_id;
  IF public.fn_accounting_tournament_fee_fingerprint(r) IS DISTINCT FROM expected->>'fingerprint'
    OR r.rake_amount<>0.10 OR r.source<>'process_tournament_rebuy' OR r.is_tournament IS DISTINCT FROM true
    OR r.created_at IS DISTINCT FROM (expected->>'charged_at')::timestamptz
    OR r.tournament_id<>event_id OR r.created_at>='2026-09-17 18:24:02.831517+00'::timestamptz THEN
   RAISE EXCEPTION 'HISTORICAL_FEE_RAW_SOURCE_DRIFT: %',record_id; END IF;
  IF t.club_id IS DISTINCT FROM (expected->>'game_club_id')::uuid OR t.union_id IS DISTINCT FROM (expected->>'union_id')::uuid
    OR t.is_private IS DISTINCT FROM false OR t.tournament_type IS DISTINCT FROM 'MTT' THEN
   RAISE EXCEPTION 'HISTORICAL_FEE_GAME_SCOPE_DRIFT: %',record_id;END IF;
  SELECT jsonb_agg(jsonb_build_object('version',v.version,'contract_hash',v.contract_hash,
      'published_at',v.published_at,'change_reason',v.change_reason) ORDER BY v.version)
    INTO actual_history FROM public.managed_game_contract_versions v
    WHERE v.game_kind='tournament' AND v.game_id=event_id AND v.published_at<=r.created_at;
  IF actual_history IS DISTINCT FROM expected->'history' OR EXISTS(
    SELECT 1 FROM public.managed_game_contract_versions v WHERE v.game_kind='tournament' AND v.game_id=event_id
     AND v.published_at<=r.created_at AND (v.contract_hash IS DISTINCT FROM
       encode(extensions.digest(convert_to(v.contract::text,'UTF8'),'sha256'),'hex')
      OR v.club_id IS DISTINCT FROM t.club_id OR v.union_id IS DISTINCT FROM t.union_id
      OR v.contract->>'id' IS DISTINCT FROM event_id::text OR v.contract->>'club_id' IS DISTINCT FROM t.club_id::text
      OR v.contract->>'union_id' IS DISTINCT FROM t.union_id::text OR v.contract->>'is_private' IS DISTINCT FROM 'false'
      OR v.contract->>'tournament_type' IS DISTINCT FROM 'MTT')) THEN
   RAISE EXCEPTION 'HISTORICAL_FEE_MANAGED_PROVENANCE_DRIFT: %',record_id;END IF;
  SELECT * INTO STRICT ent FROM public.tournament_refund_entitlements WHERE id=(expected->'entitlement'->>'id')::uuid FOR SHARE;
  IF NOT(to_jsonb(ent) @> (expected->'entitlement')) OR (SELECT count(*) FROM public.tournament_refund_entitlements e
    WHERE e.tournament_id=event_id AND e.user_id=(expected->>'player_id')::uuid AND e.created_at=r.created_at
      AND e.refund_fee=r.rake_amount AND e.entitlement_kind='wallet_charge' AND e.charge_category='rebuy')<>1 THEN
   RAISE EXCEPTION 'HISTORICAL_FEE_ENTITLEMENT_DRIFT: %',record_id;END IF;
  SELECT * INTO STRICT ledger FROM public.chip_ledger WHERE id=(expected->'ledger'->>'id')::uuid FOR SHARE;
  IF NOT(to_jsonb(ledger) @> (expected->'ledger')) THEN
   RAISE EXCEPTION 'HISTORICAL_FEE_CHARGE_DRIFT: %',record_id;END IF;
  SELECT * INTO STRICT registration FROM public.tournament_players WHERE id=(expected->'registration'->>'id')::uuid FOR SHARE;
  IF registration.tournament_id<>event_id OR registration.user_id IS DISTINCT FROM (expected->>'player_id')::uuid
    OR registration.club_id IS DISTINCT FROM (expected->>'club_id')::uuid
    OR registration.registered_at IS DISTINCT FROM (expected->'registration'->>'registered_at')::timestamptz
    OR registration.registered_at>r.created_at OR (SELECT count(*) FROM public.tournament_players p
       WHERE p.tournament_id=event_id AND p.user_id=registration.user_id)<>1 THEN
   RAISE EXCEPTION 'HISTORICAL_FEE_REGISTRATION_DRIFT: %',record_id;END IF;
  v_contract:=public.fn_accounting_earning_contract((expected->>'club_id')::uuid,(expected->>'player_id')::uuid,
    0.10,(expected->>'union_id')::uuid,r.created_at);
  IF v_contract IS DISTINCT FROM expected->'contract' THEN
   RAISE EXCEPTION 'HISTORICAL_FEE_EARNING_PROVENANCE_DRIFT: %',record_id;END IF;
  manifest:=jsonb_build_object('union_id',expected->>'union_id','game_type','mtt','spin_reserve_id',NULL,
   'contributors',jsonb_build_array(jsonb_build_object('player_id',expected->>'player_id','club_id',expected->>'club_id',
    'registration_id',registration.id,'charge_ledger_id',ledger.id,'entitlement_id',ent.id,'charged_at',r.created_at,'weight',0.10)),
   'historical_proof',jsonb_build_object('reason','Three original September 15 Free Buy rebuy charges predating fee capture',
    'evidence_version',1,'raw_fingerprint',expected->>'fingerprint','earning_authority_md5','2a8b07158f2ad3af968c1dd802e7399e'));
  IF present_batches=0 THEN
   INSERT INTO public.accounting_tournament_fee_batches(rake_record_id,tournament_id,source_fingerprint,rake_amount,source_manifest,
     status,source_version,captured_at) VALUES(record_id,event_id,expected->>'fingerprint',0.10,manifest,'captured',2,transaction_timestamp());
   INSERT INTO public.accounting_tournament_fee_sources(rake_record_id,tournament_id,player_id,club_id,union_id,coordinator_union_id,
    game_type,registration_id,source_charge_ledger_id,source_entitlement_id,charged_at,rake_credit,contract,recorded_at)
   VALUES(record_id,event_id,(expected->>'player_id')::uuid,(expected->>'club_id')::uuid,(expected->>'union_id')::uuid,
    (v_contract->>'coordinator_union_id')::uuid,'mtt',registration.id,ledger.id,ent.id,r.created_at,0.10,v_contract,transaction_timestamp());
  END IF;
  IF NOT EXISTS(SELECT 1 FROM public.accounting_tournament_fee_batches b WHERE b.rake_record_id=record_id
    AND b.tournament_id=event_id AND b.source_fingerprint=expected->>'fingerprint' AND b.rake_amount=0.10
    AND b.status='captured' AND b.source_version=2 AND b.source_manifest=manifest AND b.captured_at>r.created_at)
   OR (SELECT count(*) FROM public.accounting_tournament_fee_sources s WHERE s.rake_record_id=record_id
    AND s.tournament_id=event_id AND s.player_id=(expected->>'player_id')::uuid AND s.club_id=(expected->>'club_id')::uuid
    AND s.union_id=(expected->>'union_id')::uuid AND s.coordinator_union_id=(v_contract->>'coordinator_union_id')::uuid
    AND s.game_type='mtt' AND s.registration_id=registration.id AND s.source_charge_ledger_id=ledger.id
    AND s.source_entitlement_id=ent.id AND s.charged_at=r.created_at AND s.rake_credit=0.10
    AND s.contract=v_contract AND s.recorded_at>r.created_at)<>1 THEN
   RAISE EXCEPTION 'HISTORICAL_FEE_EXACT_CAPTURE_REQUIRED: %',record_id;END IF;
 END LOOP;
 SELECT jsonb_build_object('rake',(SELECT jsonb_agg(to_jsonb(x) ORDER BY x.id) FROM public.rake_records x WHERE x.id IN(
  'f7a5e3f5-49ce-4c17-9283-d260b39c2b0d','1229290b-448b-4015-99d2-955a093965fc','d00d2d87-9c08-44e7-80fd-6a695bc561df')))
 INTO after_evidence;
 IF after_evidence IS DISTINCT FROM before_evidence THEN RAISE EXCEPTION 'HISTORICAL_FEE_RAW_EVIDENCE_MUTATED';END IF;
 FOR target IN SELECT * FROM (VALUES
    ('2c684c36-a1c0-40c6-b92a-610a86083c1b'::uuid,0.20::numeric,2),
    ('fea2579a-643b-45d1-b22f-de654ce8ed23'::uuid,0.10::numeric,1))v(id,net_fee,contributors) LOOP
  actual:=public.fn_accounting_tournament_fee_net_plan(target.id);
  IF actual->>'status' IS DISTINCT FROM 'proven' OR (actual->>'net_fee')::numeric IS DISTINCT FROM target.net_fee
    OR (actual->>'refunded_fee')::numeric IS DISTINCT FROM 0::numeric
    OR jsonb_array_length(actual->'active_source_ids') IS DISTINCT FROM target.contributors
    OR actual->>'payable' IS DISTINCT FROM 'false' THEN
   RAISE EXCEPTION 'HISTORICAL_FEE_NET_PLAN_DRIFT: %',target.id;END IF;
 END LOOP;
 RAISE NOTICE 'HISTORICAL_FEE_PROOF: %',jsonb_build_object('sources',3,'rake_credit',0.30,'replayed',present_batches=3,'payable',false);
END;
 RAISE EXCEPTION 'HISTORICAL_FEE_PROBE_ROLLBACK: three exact sources, zero money writes' USING ERRCODE='P0001';
END $historical_fee_probe$;
